INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1707285, 230790, 16241, '<td valign="top">nice</td>', 'nice', '2005-09-14 05:34:10.000000', NULL, 1),
(1707287, 230940, 42411, '<td valign="top">Wow that looks like everyone died and went to hell. And then the citys decayed. Cool.</td>', 'Wow that looks like everyone died and went to hell. And then the citys decayed. Cool.', '2005-09-14 05:35:47.000000', NULL, 1),
(1707288, 230541, 34547, '<td valign="top">Wow! I love this. I notice that a lot of the time people will shoot candids and the people in the photo are boring and/or don''t tell a story. This photo avoids the problem and keeps me interested with the people, converging lines, and a decent choice of duotone color. 8</td>', 'Wow! I love this. I notice that a lot of the time people will shoot candids and the people in the photo are boring and/or don''t tell a story. This photo avoids the problem and keeps me interested with the people, converging lines, and a decent choice of duotone color. 8', '2005-09-14 05:36:11.000000', NULL, 1),
(1707291, 228883, 42411, '<td valign="top">Wow very creative. What are you obssesed with?</td>', 'Wow very creative. What are you obssesed with?', '2005-09-14 05:41:34.000000', NULL, 1),
(1707292, 231265, 34547, '<td valign="top">I shot from a jet, too! Nice red and attention to the crop.</td>', 'I shot from a jet, too! Nice red and attention to the crop.', '2005-09-14 05:42:46.000000', NULL, 1),
(1707295, 228757, 34547, '<td valign="top">Looks over-processed to me with a halo around the sign, in particular, but detectible in the cloud outlines. The color is alluring as well as the curved light fixtures.</td>', 'Looks over-processed to me with a halo around the sign, in particular, but detectible in the cloud outlines. The color is alluring as well as the curved light fixtures.', '2005-09-14 05:45:44.000000', NULL, 1),
(1707298, 231356, 34547, '<td valign="top">I assume this is upside down. It isn''t immediately evident but I can''t conceive this being captured any other way than from a jet. Wonderfully rich color and nice detail in the clouds.</td>', 'I assume this is upside down. It isn''t immediately evident but I can''t conceive this being captured any other way than from a jet. Wonderfully rich color and nice detail in the clouds.', '2005-09-14 05:47:09.000000', NULL, 1),
(1707302, 231310, 43589, '<td valign="top">LOVE IT</td>', 'LOVE IT', '2005-09-14 05:51:10.000000', NULL, 1),
(1707306, 230717, 34547, '<td valign="top">What happened next? I imagine the police were curious.</td>', 'What happened next? I imagine the police were curious.', '2005-09-14 05:52:40.000000', NULL, 1),
(1707308, 229322, 34547, '<td valign="top">Looks heavy on the midtones like perhaps you were trying to correct for the large, blown-out area at the top.</td>', 'Looks heavy on the midtones like perhaps you were trying to correct for the large, blown-out area at the top.', '2005-09-14 05:54:09.000000', NULL, 1),
