(1707809, 231083, 40977, '<td valign="top">I like your image and think the use of b/w works well here. Nice Job.</td>', 'I like your image and think the use of b/w works well here. Nice Job.', '2005-09-14 10:14:49.000000', NULL, 1),
(1707811, 231307, 40977, '<td valign="top">Too cool</td>', 'Too cool', '2005-09-14 10:15:19.000000', NULL, 1),
