INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1709078, 230731, 32084, '<td valign="top">Nice idea.  Maybe a little higher to get that depth and perspective, and also fairly soft on focus and not much contrast or saturation.  But, still a neat idea.</td>', 'Nice idea.  Maybe a little higher to get that depth and perspective, and also fairly soft on focus and not much contrast or saturation.  But, still a neat idea.', '2005-09-14 19:30:53.000000', NULL, 1),
(1709080, 231244, 32084, '<td valign="top">Fun - forced perspective.  Tough to pull off and get good focus.  Pretty hot on the left side.</td>', 'Fun - forced perspective.  Tough to pull off and get good focus.  Pretty hot on the left side.', '2005-09-14 19:32:07.000000', NULL, 1),
(1709082, 231032, 24951, '<td valign="top">IMO  would have more impact if rotated 90 degrees CW.</td>', 'IMO  would have more impact if rotated 90 degrees CW.', '2005-09-14 19:32:41.000000', NULL, 1),
(1709083, 231058, 42714, '<td valign="top">Interesting take on the IM Pei-designed building...made even more abstract by the lack of sky.  Like the composition, though it the reflected sky seems grainy at first glance.</td>', 'Interesting take on the IM Pei-designed building...made even more abstract by the lack of sky.  Like the composition, though it the reflected sky seems grainy at first glance.', '2005-09-14 19:33:08.000000', NULL, 1),
(1709084, 230913, 32084, '<td valign="top">Classic approach.  Too bad about the line across the middle and I''m not sure if the yellow building and its reflection add interest or distract.  I really like the tiny office lights that come through.  I wonder waht is would be like more toward dusk?</td>', 'Classic approach.  Too bad about the line across the middle and I''m not sure if the yellow building and its reflection add interest or distract.  I really like the tiny office lights that come through.  I wonder waht is would be like more toward dusk?', '2005-09-14 19:33:54.000000', NULL, 1),
(1709086, 230658, 42714, '<td valign="top">Looks like a bullet...stunning black and white, great range of tones, and wonderful use of silhouetting.  Jealous you were able to take this sort of shot.</td>', 'Looks like a bullet...stunning black and white, great range of tones, and wonderful use of silhouetting.  Jealous you were able to take this sort of shot.', '2005-09-14 19:34:24.000000', NULL, 1),
(1709087, 228649, 42808, '<td valign="top">Interesting--is it a bridge?</td>', 'Interesting--is it a bridge?', '2005-09-14 19:34:30.000000', NULL, 1),
(1709088, 230627, 18485, '<td valign="top">this is lovely...being a new yorker, i will say you overdid the saturation a bit.</td>', 'this is lovely...being a new yorker, i will say you overdid the saturation a bit.', '2005-09-14 19:34:33.000000', NULL, 1),
(1709091, 230994, 32084, '<td valign="top">I see you have gone for a lack of depth by using a longer lens.  Interesting.  The average person might have tried to exaggerate the perspective for this challenge.</td>', 'I see you have gone for a lack of depth by using a longer lens.  Interesting.  The average person might have tried to exaggerate the perspective for this challenge.', '2005-09-14 19:35:52.000000', NULL, 1),
(1709094, 231245, 42808, '<td valign="top">Interesting capture, seems to be a bit out of focus or blurred, maybe it''s my monitor</td>', 'Interesting capture, seems to be a bit out of focus or blurred, maybe it''s my monitor', '2005-09-14 19:36:39.000000', NULL, 1),
(1709096, 230731, 43024, '<td valign="top">Now, this is what I call a great picture!. The tonality is great, subtle highlights on the barrels gives a great impression, DOF is also magnificent... I would say this photo will be in the top 10, good work! I hope to see more from you!</td>', 'Now, this is what I call a great picture!. The tonality is great, subtle highlights on the barrels gives a great impression, DOF is also magnificent... I would say this photo will be in the top 10, good work! I hope to see more from you!', '2005-09-14 19:38:55.000000', NULL, 1),
(1709097, 230763, 42808, '<td valign="top">Cool image and nice "movement" effect. THis would look good in B&amp;W also.</td>', 'Cool image and nice "movement" effect. THis would look good in B&W also.', '2005-09-14 19:38:55.000000', NULL, 1),
(1709100, 230441, 42808, '<td valign="top">I like the composition and overall quality, but something''s misssing and not sure what to maintain visual interest</td>', 'I like the composition and overall quality, but something''s misssing and not sure what to maintain visual interest', '2005-09-14 19:41:28.000000', NULL, 1),
(1709104, 230477, 43031, '<td valign="top">Needs more contrast, left side is washed out beyond repair (user higher shutter speed, or try a graduated ND filter), and the ship looks a little bit fuzzy. Try putting moving objects with more space in front of them to make them look like they''re going somewhere.</td>', 'Needs more contrast, left side is washed out beyond repair (user higher shutter speed, or try a graduated ND filter), and the ship looks a little bit fuzzy. Try putting moving objects with more space in front of them to make them look like they''re going somewhere.', '2005-09-14 19:42:59.000000', NULL, 1),
(1709105, 229680, 42808, '<td valign="top">Good subject and composition.</td>', 'Good subject and composition.', '2005-09-14 19:43:03.000000', NULL, 1),
(1709107, 230822, 43031, '<td valign="top">Nice angle, wish you had had some clouds or something to put in all that blue over there.</td>', 'Nice angle, wish you had had some clouds or something to put in all that blue over there.', '2005-09-14 19:43:54.000000', NULL, 1),
(1709108, 229165, 42808, '<td valign="top">Wow--very good capture, composition and lighting. A 9 on my list</td>', 'Wow--very good capture, composition and lighting. A 9 on my list', '2005-09-14 19:45:16.000000', NULL, 1),
