(1710434, 231081, 38671, '<td valign="top">A very reflective shot of an urban late afternoon...Striking yet peaceful.</td>', 'A very reflective shot of an urban late afternoon...Striking yet peaceful.', '2005-09-15 01:00:36.000000', NULL, 1),
(1710438, 231012, 37930, '<td valign="top">I think it woulda been cooler had you been able to see the whole edge of the window. Cool idea though.</td>', 'I think it woulda been cooler had you been able to see the whole edge of the window. Cool idea though.', '2005-09-15 01:01:18.000000', NULL, 1),
