(1712368, 231063, 41510, '<td valign="top">Very clever. Good technically.</td>', 'Very clever. Good technically.', '2005-09-15 19:08:59.000000', NULL, 1),
(1712370, 229960, 37409, '<td valign="top">Austin, TX :) Nice capture.. Was a tripod with timed shutter release used? Looks a little shakey.</td>', 'Austin, TX :) Nice capture.. Was a tripod with timed shutter release used? Looks a little shakey.', '2005-09-15 19:09:09.000000', NULL, 1),
