(1712383, 229862, 37409, '<td valign="top">I would have gotten down on the ground and tried to make that stream look like a sulfer river.. the scenary in the distance takes away from that cool yellow water.</td>', 'I would have gotten down on the ground and tried to make that stream look like a sulfer river.. the scenary in the distance takes away from that cool yellow water.', '2005-09-15 19:14:18.000000', NULL, 1),
(1712385, 229382, 37409, '<td valign="top">White Balance.. Too hot.</td>', 'White Balance.. Too hot.', '2005-09-15 19:14:40.000000', NULL, 1),
