(1712410, 230781, 37961, '<td valign="top">Love the sky.</td>', 'Love the sky.', '2005-09-15 19:25:26.000000', NULL, 1),
(1712413, 230630, 42100, '<td valign="top">Would be more interesting with windmills spread across the entire photo IMO (i.e. asome seperation between towers.  The cutoff towers take away from your photo, mainly the close large one, perhaps a vertical format would help here.</td>', 'Would be more interesting with windmills spread across the entire photo IMO (i.e. asome seperation between towers.  The cutoff towers take away from your photo, mainly the close large one, perhaps a vertical format would help here.', '2005-09-15 19:25:41.000000', NULL, 1),
(1712414, 230828, 37961, '<td valign="top">Love it. Great focus and DOF.....love the dog and ball.</td>', 'Love it. Great focus and DOF.....love the dog and ball.', '2005-09-15 19:25:45.000000', NULL, 1),
(1712417, 231354, 42837, '<td valign="top">Great composition, you caught it at just the right time of day with the perpendicular shadows enhancing the visual cues. The arrow was well spotted and placed too.</td>', 'Great composition, you caught it at just the right time of day with the perpendicular shadows enhancing the visual cues. The arrow was well spotted and placed too.', '2005-09-15 19:25:56.000000', NULL, 1),
(1712420, 231197, 42100, '<td valign="top">Very funny!  Brave model.</td>', 'Very funny!  Brave model.', '2005-09-15 19:26:48.000000', NULL, 1),
