(1712517, 230962, 42410, '<td valign="top">very nice. I like the perspective and the use of blue.</td>', 'very nice. I like the perspective and the use of blue.', '2005-09-15 20:15:56.000000', NULL, 1),
(1712519, 229126, 34547, '<td valign="top">Looks like a bit too much Unsharp Mask, but the lines and color are interesting.</td>', 'Looks like a bit too much Unsharp Mask, but the lines and color are interesting.', '2005-09-15 20:16:13.000000', NULL, 1),
