(1723918, 231064, 36621, '<td valign="top">Interesting shot,  but the crooked horizon line just doesn''t work.</td>', 'Interesting shot,  but the crooked horizon line just doesn''t work.', '2005-09-20 12:32:15.000000', NULL, 1),
(1723921, 231032, 41581, '<td valign="top">Lighting is too low.</td>', 'Lighting is too low.', '2005-09-20 12:34:23.000000', NULL, 1),
