(1725960, 231254, 23430, '<td valign="top">Great idea, had me thinking for a long time.</td>', 'Great idea, had me thinking for a long time.', '2005-09-21 00:54:11.000000', NULL, 1),
(1725963, 229165, 39411, '<td valign="top">Great perspective and composition.</td>', 'Great perspective and composition.', '2005-09-21 00:54:51.000000', NULL, 1),
