(1725974, 231357, 37961, '<td valign="top">Very good take on the challenge. Love the composition and the color of the dust.</td>', 'Very good take on the challenge. Love the composition and the color of the dust.', '2005-09-21 00:57:28.000000', NULL, 1),
(1725976, 229802, 39411, '<td valign="top">I guess this is a chain on the dock?!  Without more information in the background, I can''t really tell where this was taken. Perhaps a different background...boat or more depth of field to show more water.</td>', 'I guess this is a chain on the dock?!  Without more information in the background, I can''t really tell where this was taken. Perhaps a different background...boat or more depth of field to show more water.', '2005-09-21 00:57:39.000000', NULL, 1),
(1725978, 231167, 37961, '<td valign="top">Thats extreme. Makes me dizzy! Good job.</td>', 'Thats extreme. Makes me dizzy! Good job.', '2005-09-21 00:57:58.000000', NULL, 1),
(1725986, 229090, 23430, '<td valign="top">This has good composition. I think you may have been better going for a longer DOF or making the person to be in focus.</td>', 'This has good composition. I think you may have been better going for a longer DOF or making the person to be in focus.', '2005-09-21 00:58:55.000000', NULL, 1),
