INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1725992, 230418, 34659, '<td valign="top">Absolutely oustanding shot!  Congrats!</td>', 'Absolutely oustanding shot!  Congrats!', '2005-09-21 01:03:20.000000', NULL, 0),
(1725993, 231286, 13772, '<td valign="top">Thanks everyone for the comments on my photo. I will watch the horizon a little better. All comments helped.</td>', 'Thanks everyone for the comments on my photo. I will watch the horizon a little better. All comments helped.', '2005-09-21 01:03:37.000000', NULL, 0),
(1725996, 229120, 22379, '<td valign="top">wow what an amazing staircase! Is that a pool at the bottom?!??!Congrats on the ribbon Keith :D</td>', 'wow what an amazing staircase! Is that a pool at the bottom?!??!Congrats on the ribbon Keith :D', '2005-09-21 01:06:03.000000', NULL, 0),
(1726002, 228959, 39665, '<td valign="top">very nice photo....i gave it a 10<br/>congrats!!!!</td>', 'very nice photo....i gave it a 10congrats!!!!', '2005-09-21 01:22:15.000000', NULL, 0),
(1726006, 230793, 19116, '<td valign="top">Thanks for all the great comments!  The photo is the underside of the portico at the ING building in downtown Minneapolis.  It was taken at night.  The "vertical lines" are the columns holding the roof up (the photo is flipped upside down).  The building is not really green, this was a product of the inability of the auto white balance on my camera to deal with the bright lights on the underside of the roof.  I decided I liked the green, and even increased it some in post-processing.</td>', 'Thanks for all the great comments!  The photo is the underside of the portico at the ING building in downtown Minneapolis.  It was taken at night.  The "vertical lines" are the columns holding the roof up (the photo is flipped upside down).  The building is not really green, this was a product of the inability of the auto white balance on my camera to deal with the bright lights on the underside of the roof.  I decided I liked the green, and even increased it some in post-processing.', '2005-09-21 01:29:43.000000', NULL, 0),
(1726007, 230378, 42826, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by iisliii:</b></div><hr/><i> LAME </i></td></tr></table> <br/> <br/>I don''t feel that this comment is appropriate.  Different wording would have been a better decision.</td>', 'Originally posted by iisliii: LAME   I don''t feel that this comment is appropriate.  Different wording would have been a better decision.', '2005-09-21 01:33:22.000000', NULL, 0),
(1726010, 230418, 24495, '<td valign="top">Wonderful image!Congrats. <br/>A question though. Is noise removing permitted in open challenge?</td>', 'Wonderful image!Congrats. A question though. Is noise removing permitted in open challenge?', '2005-09-21 01:35:26.000000', NULL, 0),
(1726023, 230418, 37902, '<td valign="top">Congrats! Very beautiful. How does the original look like?</td>', 'Congrats! Very beautiful. How does the original look like?', '2005-09-21 02:08:28.000000', NULL, 0),
(1726025, 230418, 37902, '<td valign="top">Congrats! Very beautiful. How does the original look like?</td>', 'Congrats! Very beautiful. How does the original look like?', '2005-09-21 02:12:09.000000', NULL, 0),
